BEGIN;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, instructions TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), project_id TEXT REFERENCES projects(id), status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, name TEXT NOT NULL, effect TEXT NOT NULL, priority INTEGER NOT NULL, enabled BOOLEAN NOT NULL, definition JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, requested_by TEXT NOT NULL, resource_id TEXT NOT NULL, action TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL, decision_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS executions (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), resource_id TEXT NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL, retries INTEGER NOT NULL DEFAULT 0, checkpoint_id TEXT, cost JSONB, tokens JSONB, result JSONB, error JSONB, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS checkpoints (id TEXT PRIMARY KEY, execution_id TEXT NOT NULL REFERENCES executions(id), phase TEXT NOT NULL, state JSONB NOT NULL, valid BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS budgets (id TEXT PRIMARY KEY, owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, definition JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT, risk TEXT NOT NULL, decision TEXT NOT NULL, metadata JSONB NOT NULL, digest TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO schema_migrations(version) VALUES ('002_control_plane') ON CONFLICT DO NOTHING;
COMMIT;